import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"ADR-012: A project dashboard with write actions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/012-project-dashboard.md","filePath":"adr/012-project-dashboard.md"}'),i={name:"adr/012-project-dashboard.md"};function s(n,e,d,c,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-012-a-project-dashboard-with-write-actions" tabindex="-1">ADR-012: A project dashboard with write actions <a class="header-anchor" href="#adr-012-a-project-dashboard-with-write-actions" aria-label="Permalink to &quot;ADR-012: A project dashboard with write actions&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-16</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-002 keeps YAML as the only authoring surface and the per-episode studio writes only <code>cues.json</code>. Users who do not work in a terminal also expect a graphical entry point: creating episodes, adding a recording, starting renders and finding the results without a terminal.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><code>reelforge studio</code> serves a dashboard (localhost only) whose write actions are limited to project housekeeping, never scene data:</p><ul><li>create an episode from the template (<code>episodes/&lt;id&gt;/episode.yaml</code>),</li><li>store an uploaded recording as the episode&#39;s voice file (converted to WAV with ffmpeg),</li><li>write draft cues when none exist,</li><li>start/cancel one render job, open the per-episode studio, open a folder in the file manager.</li></ul><p>Security: bound to 127.0.0.1, Host/Origin checks on every request and WebSocket, JSON-only POST bodies (blocks HTML-form CSRF), every path resolved inside the project root, output files served only from <code>out/</code>, uploads capped at 1 GB and limited to audio extensions.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Scene design stays in YAML (reviewable, diff-able). Non-technical users can run the whole workflow from the browser; the CLI remains the automation surface.</p>',10)])])}const f=o(i,[["render",s]]);export{u as __pageData,f as default};
